import math


def _point(value, name):
    if not isinstance(value, (list, tuple)) or len(value) != 2:
        raise ValueError(name + " must contain two coordinates")
    result = []
    for coordinate in value:
        if isinstance(coordinate, bool) or not isinstance(coordinate, (int, float)):
            raise TypeError("coordinates must be numeric")
        if not math.isfinite(coordinate):
            raise ValueError("coordinates must be finite")
        result.append(coordinate)
    return result


def analyze_trajectory(points, target, radius):
    if not isinstance(points, (list, tuple)):
        raise TypeError("points must be a sequence")
    if isinstance(radius, bool) or not isinstance(radius, (int, float)):
        raise TypeError("radius must be numeric")
    if not math.isfinite(radius) or radius < 0:
        raise ValueError("radius must be finite and non-negative")
    checked_target = _point(target, "target")
    path = [_point(point, "point") for point in points]
    distances = [math.hypot(point[0] - checked_target[0], point[1] - checked_target[1]) for point in path]
    first = next((index for index, distance in enumerate(distances) if distance < radius), None)
    return {"distances": distances, "first_reached": first, "path": [point[:] for point in path]}

